from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(amount="80.00", status="captured", refunded="0.00"):
    return Payment("pay_1","inv_1",Decimal(amount),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(refunded))

# partial then full
pay = p()
outage_refund(pay, Decimal("30.00"), T0)
print(pay.refunded_amount, pay.status)
outage_refund(pay, Decimal("50.00"), T0)
print(pay.refunded_amount, pay.status)

# over-refund
try: outage_refund(p(), Decimal("80.01"), T0)
except BillingError as e: print("err", e.code)
# non-positive
for a in (Decimal("0"), Decimal("-1")):
    try: outage_refund(p(), a, T0)
    except BillingError as e: print("err", e.code)
# not captured
try: outage_refund(p(status="authorized"), Decimal("1"), T0)
except BillingError as e: print("err", e.code)
# approval threshold
try: outage_refund(p(amount="2000.00"), Decimal("1000.01"), T0)
except BillingError as e: print("err", e.code)
print(outage_refund(p(amount="2000.00"), Decimal("1000.01"), T0, approved_by="mgr").refunded_amount)
print(outage_refund(p(amount="2000.00"), Decimal("1000.00"), T0).refunded_amount)
EOF"}

